import{_ as p,a0 as l,w as o,s as r,ao as d,I as n,x as s,a1 as i,A as t}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const v=JSON.parse('{"title":"科學音頻處理（一）：怎樣使用 Octave 對音頻文件進行讀寫操作 | LCTT x X-CMD","titleTemplate":false,"description":"科學音頻處理（一）：怎樣使用 Octave 對音頻文件進行讀寫操作 | LCTT (201609) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"科學音頻處理（一）：怎樣使用 Octave 對音頻文件進行讀寫操作 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"科學音頻處理（一）：怎樣使用 Octave 對音頻文件進行讀寫操作 | LCTT (201609) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201609/20160616 Part 1 - Scientific Audio Processing How to read and write Audio files with Octave 4.0.0 on Ubuntu","title":"科學音頻處理（一）：怎樣使用 Octave 對音頻文件進行讀寫操作","tag":"201609","desc":""},"relativePath":"201609/20160616 Part 1 - Scientific Audio Processing How to read and write Audio files with Octave 4.0.0 on Ubuntu.md","filePath":"[post].md"}'),g={name:"201609/20160616 Part 1 - Scientific Audio Processing How to read and write Audio files with Octave 4.0.0 on Ubuntu.md"};function h(c,a,u,f,b,k){const e=l("Link");return o(),r("div",null,[a[13]||(a[13]=d(`<h1 id="科學音頻處理-一-怎樣使用-octave-對音頻文件進行讀寫操作" tabindex="-1">科學音頻處理（一）：怎樣使用 Octave 對音頻文件進行讀寫操作 <a class="header-anchor" href="#科學音頻處理-一-怎樣使用-octave-對音頻文件進行讀寫操作" aria-label="Permalink to “科學音頻處理（一）：怎樣使用 Octave 對音頻文件進行讀寫操作”">​</a></h1><p>Octave 是一個類似於 Linux 上的 Matlab 的軟件，它擁有數量眾多的函數和命令，支持聲音採集、記錄、回放以及音頻信號的數字化處理，用於娛樂應用、研究、醫學以及其它科學領域。在本教程中，我們會在 Ubuntu 上使用 Octave 的 4.0.0 版本讀取音頻文件，然後通過生成信號並且播放來模仿在各種情況下對音頻信號的使用。</p><p>本教程中關注的不是安裝和學習使用安裝好的音頻處理軟件，而是從設計和音頻工程的角度理解它是如何工作的。</p><h3 id="環境準備" tabindex="-1">環境準備 <a class="header-anchor" href="#環境準備" aria-label="Permalink to “環境準備”">​</a></h3><p>首先是安裝 octave，在 Ubuntu 終端運行下面的命令添加 Octave PPA，然後安裝 Octave 。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt-add-repository ppa:octave/stable</span></span>
<span class="line"><span>sudo apt-get update</span></span>
<span class="line"><span>sudo apt-get install octave</span></span></code></pre></div><h3 id="步驟1-打開-octave" tabindex="-1">步驟1：打開 Octave <a class="header-anchor" href="#步驟1-打開-octave" aria-label="Permalink to “步驟1：打開 Octave”">​</a></h3><p>在這一步中我們單擊軟件圖標打開 Octave，可以通過單擊下拉式按鈕選擇工作路徑。</p><p><img src="https://www.howtoforge.com/images/how-to-read-and-write-audio-files-with-octave-4-in-ubuntu/initial.png" alt=""></p><h3 id="步驟2-音頻信息" tabindex="-1">步驟2：音頻信息 <a class="header-anchor" href="#步驟2-音頻信息" aria-label="Permalink to “步驟2：音頻信息”">​</a></h3><p>使用<code>audioinfo</code>命令查看要處理的音頻文件的相關信息。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&gt;&gt; info = audioinfo (&#39;testing.ogg&#39;)</span></span></code></pre></div><p><img src="https://www.howtoforge.com/images/how-to-read-and-write-audio-files-with-octave-4-in-ubuntu/audioinfo.png" alt=""></p><h3 id="步驟3-讀取音頻文件" tabindex="-1">步驟3：讀取音頻文件 <a class="header-anchor" href="#步驟3-讀取音頻文件" aria-label="Permalink to “步驟3：讀取音頻文件”">​</a></h3><p>在本教程中我會使用 ogg 文件來讀取這種文件的屬性，比如採樣、音頻類型（stereo 和 mono）、信道數量等。必須聲明的一點是教程中使用的所有的命令都是在 Octave 終端窗口中執行的。首先，我們必須要把這個 ogg 文件賦給一個變量。注意：<strong>文件必須在 Octave 的工作路徑中。</strong></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&gt;&gt; file=&#39;yourfile.ogg&#39;</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&gt;&gt; [M, fs] = audioread(file)</span></span></code></pre></div><p>這裏的 M 是一個一列或兩列的矩陣，取決於信道的數量，fs 是採樣率。</p><p><img src="https://www.howtoforge.com/images/how-to-read-and-write-audio-files-with-octave-4-in-ubuntu/reading.png" alt=""></p><p><img src="https://www.howtoforge.com/images/how-to-read-and-write-audio-files-with-octave-4-in-ubuntu/matrix.png" alt=""></p><p><img src="https://www.howtoforge.com/images/how-to-read-and-write-audio-files-with-octave-4-in-ubuntu/big/frequency.png" alt=""></p><p>下面的操作都可以讀取音頻文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&gt;&gt; [y, fs] = audioread (filename, samples)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>&gt;&gt; [y, fs] = audioread (filename, datatype)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>&gt;&gt; [y, fs] = audioread (filename, samples, datatype)</span></span></code></pre></div><p>samples 指定開始幀和結束幀，datatype 指定返回的數據類型。可以為所有變量設置值：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&gt;&gt; samples = [1, fs)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>&gt;&gt; [y, fs] = audioread (filename, samples)</span></span></code></pre></div><p>數據類型：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&gt;&gt; [y,Fs] = audioread(filename,&#39;native&#39;)</span></span></code></pre></div><p>如果值是“native”，那麼它的數據類型就依數據在音頻文件中的存儲情況而定。</p><h3 id="步驟4-音頻文件的寫操作" tabindex="-1">步驟4：音頻文件的寫操作 <a class="header-anchor" href="#步驟4-音頻文件的寫操作" aria-label="Permalink to “步驟4：音頻文件的寫操作”">​</a></h3><p>新建一個 ogg 文件：</p><p>我們會從一個餘弦值創建一個 ogg 文件。採樣率是每秒 44100 次，這個文件最少進行 10 秒的採樣。餘弦信號的頻率是 440 Hz。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&gt;&gt; filename=&#39;cosine.ogg&#39;;</span></span>
<span class="line"><span>&gt;&gt; fs=44100;</span></span>
<span class="line"><span>&gt;&gt; t=0:1/fs:10;</span></span>
<span class="line"><span>&gt;&gt; w=2*pi*440*t;</span></span>
<span class="line"><span>&gt;&gt; signal=cos(w);</span></span>
<span class="line"><span>&gt;&gt; audiowrite(filename, signal, fs);</span></span></code></pre></div><p>這就在工作路徑中創建了一個 &#39;cosine.ogg&#39; 文件，這個文件中包含餘弦信號。</p><p><img src="https://www.howtoforge.com/images/how-to-read-and-write-audio-files-with-octave-4-in-ubuntu/cosinefile.png" alt=""></p><p>播放這個 &#39;cosine.ogg&#39; 文件就會產生一個 440Hz 的 音調，這個音調正好是樂理中的 &#39;A&#39; 調。如果需要查看保存在文件中的值就必須使用 &#39;audioread&#39; 函數讀取文件。在後續的教程中，我們會看到怎樣在兩個信道中讀取一個音頻文件。</p><h3 id="步驟5-播放音頻文件" tabindex="-1">步驟5：播放音頻文件 <a class="header-anchor" href="#步驟5-播放音頻文件" aria-label="Permalink to “步驟5：播放音頻文件”">​</a></h3><p>Octave 有一個默認的音頻播放器，可以用這個音頻播放器進行測試。使用下面的函數：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&gt;&gt; [y,fs]=audioread(&#39;yourfile.ogg&#39;);</span></span>
<span class="line"><span>&gt;&gt; player=audioplayer(y, fs, 8)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  scalar structure containing the fields:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    BitsPerSample =  8</span></span>
<span class="line"><span>    CurrentSample = 0</span></span>
<span class="line"><span>    DeviceID = -1</span></span>
<span class="line"><span>    NumberOfChannels =  1</span></span>
<span class="line"><span>    Running = off</span></span>
<span class="line"><span>    SampleRate =  44100</span></span>
<span class="line"><span>    TotalSamples =  236473</span></span>
<span class="line"><span>    Tag =</span></span>
<span class="line"><span>    Type = audioplayer</span></span>
<span class="line"><span>    UserData = [](0x0)</span></span>
<span class="line"><span>&gt;&gt; play(player);</span></span></code></pre></div><p>在這個教程的續篇，我們會進入音頻處理的高級特性部分，可能會接觸到一些科學和商業應用中的實例。</p><hr>`,40)),n("p",null,[a[1]||(a[1]=s("via: ",-1)),i(e,{href:"https://www.howtoforge.com/tutorial/how-to-read-and-write-audio-files-with-octave-4-in-ubuntu/"},{default:t(()=>[...a[0]||(a[0]=[s("https://www.howtoforge.com/tutorial/how-to-read-and-write-audio-files-with-octave-4-in-ubuntu/",-1)])]),_:1})]),n("p",null,[a[5]||(a[5]=s("作者：",-1)),i(e,{href:"https://twitter.com/intent/follow?original_referer=https%3A%2F%2Fwww.howtoforge.com%2Ftutorial%2Fhow-to-read-and-write-audio-files-with-octave-4-in-ubuntu%2F&ref_src=twsrc%5Etfw&region=follow_link&screen_name=howtoforgecom&tw_p=followbutton"},{default:t(()=>[...a[2]||(a[2]=[s("David Duarte",-1)])]),_:1}),a[6]||(a[6]=s(" 譯者：",-1)),i(e,{href:"https://github.com/vim-kakali"},{default:t(()=>[...a[3]||(a[3]=[s("vim-kakali",-1)])]),_:1}),a[7]||(a[7]=s(" 校對：",-1)),i(e,{href:"https://github.com/wxy"},{default:t(()=>[...a[4]||(a[4]=[s("wxy",-1)])]),_:1})]),n("p",null,[a[10]||(a[10]=s("本文由 ",-1)),i(e,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...a[8]||(a[8]=[s("LCTT",-1)])]),_:1}),a[11]||(a[11]=s(" 原創編譯，",-1)),i(e,{href:"https://linux.cn/"},{default:t(()=>[...a[9]||(a[9]=[s("Linux中國",-1)])]),_:1}),a[12]||(a[12]=s(" 榮譽推出",-1))])])}const y=p(g,[["render",h]]);export{v as __pageData,y as default};
